import{c as a,Q as r,J as l,h as e,e as t,m as n,l as i,k as c}from"./chunks/framework.WgZQdPFo.js";const f=JSON.parse('{"title":"Товары (Витрина)","description":"Управление складом готовой продукции, инвентаризация и FIFO-себестоимость в ОмниКрафт ЕРП.","frontmatter":{"title":"Товары (Витрина)","description":"Управление складом готовой продукции, инвентаризация и FIFO-себестоимость в ОмниКрафт ЕРП.","order":8},"headers":[],"relativePath":"ru/docs/spaces/production/showcase.md","filePath":"ru/docs/spaces/production/showcase.md"}'),d={name:"ru/docs/spaces/production/showcase.md"},p={id:"товары-витрина-и-склад-готовои-продукции",tabindex:"-1"};function h(g,o,u,m,b,k){const s=r("DocIcon");return l(),e("div",null,[t("h1",p,[n(s,{name:"showcase"}),o[0]||(o[0]=i(" Товары: Витрина и склад готовой продукции ",-1)),o[1]||(o[1]=t("a",{class:"header-anchor",href:"#товары-витрина-и-склад-готовои-продукции","aria-label":'Permalink to "<DocIcon name="showcase" /> Товары: Витрина и склад готовой продукции"'},"​",-1))]),o[2]||(o[2]=c('<p>Вкладка <strong>«Товары»</strong> — это складской реестр готовой продукции. Здесь отображается актуальный физический остаток всех произведенных вами изделий, их фактическая себестоимость партий (по скользящей средней МАК) и рекомендуемая розничная цена для продажи.</p><p>Товары не появляются здесь из воздуха. Чтобы товар появился на складе, он должен пройти через вкладку <a href="./workbench">«В производстве»</a> (быть изготовленным на Верстаке).</p><hr><h2 id="режимы-отображения-склада" tabindex="-1">Режимы отображения склада <a class="header-anchor" href="#режимы-отображения-склада" aria-label="Permalink to &quot;Режимы отображения склада&quot;">​</a></h2><p>В правой части верхней панели инструментов расположен переключатель вида:</p><ul><li><strong>Складские строки (по умолчанию):</strong> компактный операционный реестр с квадратными миниатюрами изделий (1:1), точными остатками, фактической МАК-себестоимостью, расчетной ценой и кнопкой быстрой инвентаризации в каждой строке. Идеально подходит для ежедневной складской работы с большим количеством позиций.</li><li><strong>Карточки изделий:</strong> просторная плиточная сетка карточек с развернутой сводкой характеристик и счетчиком всего произведенного тиража.</li></ul><hr><h2 id="карточка-и-учетные-параметры-товара" tabindex="-1">Карточка и учетные параметры товара <a class="header-anchor" href="#карточка-и-учетные-параметры-товара" aria-label="Permalink to &quot;Карточка и учетные параметры товара&quot;">​</a></h2><p>Каждое изделие сопровождается квадратной миниатюрой (1:1), загружаемой из фотографий изделия или витрины, и ключевыми метриками:</p><ul><li><strong>В наличии:</strong> Текущий физический остаток на складе.</li><li><strong>Всего произведено:</strong> Исторический счетчик (сколько таких изделий вы сшили за всё время работы в программе).</li><li><strong>Рекомендуемая розничная цена (РРЦ):</strong> Цена, которую программа автоматически вычислила на базе себестоимости и вашей Глобальной наценки (из Настроек).</li></ul><h3 id="двоиная-себестоимость-по-калькулятору-и-фактическая" tabindex="-1">Двойная себестоимость (По калькулятору и фактическая) <a class="header-anchor" href="#двоиная-себестоимость-по-калькулятору-и-фактическая" aria-label="Permalink to &quot;Двойная себестоимость (По калькулятору и фактическая)&quot;">​</a></h3><p>Если у вас есть товар в наличии, на карточке вы увидите сразу две цифры себестоимости:</p><ol><li><strong>По калькулятору:</strong> Это <em>теоретическая</em> себестоимость изделия, если бы вы начали шить его прямо сейчас из текущих запасов сырья.</li><li><strong>Себестоимость остатка:</strong> Это <em>фактическая</em> себестоимость тех конкретных изделий, которые лежат у вас на полке в данный момент. Она берется из тех партий, которые вы реально сшили ранее.</li></ol><div class="info custom-block"><p class="custom-block-title">Зачем нужны две себестоимости? (Метод ФИФО)</p><p>Представьте: вы сшили сумку месяц назад, когда кожа стоила дешево. Себестоимость той сумки составила 3 000 ₽. Сумка легла на полку. Сегодня кожа сильно подорожала. Калькулятор показывает, что сшить такую же сумку сейчас стоит 5 000 ₽. Если бы программа просто обновила цену старой сумки до 5 000 ₽, ваша прибыль при продаже исказилась бы. ОмниКрафт ЕРП так не делает. Программа помнит, что на полке лежит именно та, старая сумка за 3 000 ₽, и при продаже спишет именно эту цифру, обеспечив вам 100% точность расчета чистой прибыли. Это называется методом <strong>ФИФО (First In, First Out)</strong>.</p></div><hr><h2 id="инвентаризация-изделии" tabindex="-1">Инвентаризация изделий <a class="header-anchor" href="#инвентаризация-изделии" aria-label="Permalink to &quot;Инвентаризация изделий&quot;">​</a></h2><p>Как и на складе сырья, физическая реальность иногда расходится с данными в программе (например, вы подарили кошелек другу и забыли это отметить, или наоборот, нашли на полке брелок, который забыли зачислить с верстака).</p><p>Для исправления таких ситуаций на каждой карточке товара есть кнопка <strong>«Инвентаризация»</strong>.</p><ol><li>Выберите тип: <strong>Оприходовать излишек (+)</strong> или <strong>Списать недостачу (-)</strong>.</li><li>Укажите количество штук.</li><li>Нажмите «Провести».</li></ol><h3 id="как-инвентаризация-влияет-на-финансы" tabindex="-1">Как инвентаризация влияет на финансы? <a class="header-anchor" href="#как-инвентаризация-влияет-на-финансы" aria-label="Permalink to &quot;Как инвентаризация влияет на финансы?&quot;">​</a></h3><p>Инвентаризация готовых товаров <strong>абсолютно безопасна для кассы</strong>.</p><ul><li>При списании недостачи программа просто удалит самые старые партии товара (по ФИФО) со склада. Деньги из ДДС не спишутся, так как это просто корректировка учета.</li><li>При оприходовании излишка программа добавит товар на полку, присвоив ему <em>текущую оценочную себестоимость</em> из Калькулятора.</li></ul><div class="warning custom-block"><p class="custom-block-title">Не используйте инвентаризацию для продаж!</p><p>Списание недостачи просто удаляет товар со склада, не принося вам выручки. Если вы отдали товар клиенту, всегда проводите это через вкладку <strong>«Продажи»</strong>, даже если вы сделали 100% скидку (в этом случае просто укажите цену продажи 0 ₽, и программа честно зафиксирует убыток на себестоимость этого товара).</p></div><hr><h2 id="фильтрация-склада-и-управление-архивом-изделии" tabindex="-1">Фильтрация склада и управление архивом изделий <a class="header-anchor" href="#фильтрация-склада-и-управление-архивом-изделии" aria-label="Permalink to &quot;Фильтрация склада и управление архивом изделий&quot;">​</a></h2><p>В верхней панели склада расположен трехпозиционный переключатель статуса:</p><ul><li><strong>«Все»:</strong> полный каталог активных изделий мастерской (включая позиции с нулевым складским остатком).</li><li><strong>«В наличии»:</strong> только те изделия, которые физически присутствуют на полке склада (<code>остаток &gt; 0</code>).</li><li><strong>«В архиве»:</strong> изделия, выведенные из активного ассортимента мастерской.</li></ul><h3 id="как-отправить-изделие-в-архив" tabindex="-1">Как отправить изделие в архив <a class="header-anchor" href="#как-отправить-изделие-в-архив" aria-label="Permalink to &quot;Как отправить изделие в архив&quot;">​</a></h3><p>Если модель снята с производства или не планируется к выпуску в текущем сезоне:</p><ol><li>Нажмите кнопку <strong>«Отправить изделие в архив»</strong> (иконка архива) в правой части строки изделия.</li><li>Программа проверит статус заказов: <ul><li><strong>Защита от незавершенного производства (WIP):</strong> Если изделие в данный момент находится на Верстаке в процессе изготовления, архивация будет заблокирована. Сначала завершите изготовление или отмените заказ.</li><li><strong>Наличие остатка:</strong> Если на складе остались готовые экземпляры, программа предупредит об этом. Вы сможете отправить модель в архив — физический остаток и партии ФИФО сохранятся, но запуск нового производства на Верстаке будет заблокирован.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Технологическая карта сохраняется</p><p>При отправке изделия в архив его технологический паспорт (состав сырья, фурнитура и норматив времени) не удаляется. В разделе «Калькулятор» связанная техкарта синхронно перемещается в подраздел «Архив рецептов». Вы всегда сможете восстановить ее в один клик.</p></div><h3 id="восстановление-и-удаление-из-архива" tabindex="-1">Восстановление и удаление из архива <a class="header-anchor" href="#восстановление-и-удаление-из-архива" aria-label="Permalink to &quot;Восстановление и удаление из архива&quot;">​</a></h3><p>Переключите тумблер в положение <strong>«В архиве»</strong>:</p><ul><li><strong>Восстановить изделие:</strong> нажмите кнопку со стрелкой из архива — изделие вернется в активный список склада, а его техкарта снова станет доступна для запуска в Калькуляторе.</li><li><strong>Удалить навсегда:</strong> нажмите кнопку с корзиной.</li></ul><div class="danger custom-block"><p class="custom-block-title">Защита от потери складской капитализации</p><p>Удалить изделие навсегда можно <strong>строго при нулевом остатке на складе</strong> (<code>0 шт.</code>). Если за позицией числится хотя бы одна единица, программа заблокирует удаление. Сначала спишите физический остаток через кнопку <strong>«Инвентаризация»</strong> или проведите продажу, чтобы себестоимость партий не зависла в финансовом капитале мастерской.</p></div>',35))])}const q=a(d,[["render",h]]);export{f as __pageData,q as default};
